func diff(curResults, preResults models.ScanResults, plus, minus bool) (diffed models.ScanResults, err error) {
	for _, current := range curResults {
		var previous models.ScanResult
		for _, r := range preResults {
			if current.ServerName == r.ServerName && current.Container.Name == r.Container.Name {
				previous = r
				break
			}
		}

		currentPackages := current.Packages
		current.ScannedCves = getDiffCves(previous, current, plus, minus)
		packages := models.Packages{}
		for _, status := range []models.DiffStatus{models.DiffMinus, models.DiffPlus} {
			source := previous.Packages
			if status == models.DiffPlus {
				source = currentPackages
			}
			for _, vuln := range current.ScannedCves {
				if vuln.DiffStatus != status {
					continue
				}
				for _, affected := range vuln.AffectedPackages {
					if pkg, ok := source[affected.Name]; ok {
						packages[affected.Name] = pkg
					}
				}
			}
		}
		// A package can appear in both a new and a resolved CVE. The shared
		// Packages map cannot hold two versions under the same name, so keep
		// the other version on the CVE that needs it.
		for cveID, vuln := range current.ScannedCves {
			source := currentPackages
			if vuln.DiffStatus == models.DiffMinus {
				source = previous.Packages
			}
			for _, affected := range vuln.AffectedPackages {
				pkg, ok := source[affected.Name]
				if !ok {
					continue
				}
				if selected, found := packages[affected.Name]; found && !reflect.DeepEqual(selected, pkg) {
					if vuln.DiffPackages == nil {
						vuln.DiffPackages = models.Packages{}
					}
					vuln.DiffPackages[affected.Name] = pkg
				}
			}
			current.ScannedCves[cveID] = vuln
		}
		current.Packages = packages

		diffed = append(diffed, current)
	}
	return diffed, err
}

